export interface StructuredDsaTestCase {
  arguments: unknown[];
  expectedValue: unknown;
  mode?: "return" | "mutated-first-argument";
  comparison?: "exact" | "unordered" | "unordered-nested" | "unordered-deep" | "one-of";
  /**
   * Arguments the generated program builds rather than reading from a literal,
   * so a case can be large enough that wrong complexity runs out of time.
   * `arguments` still holds a small value of the same shape for type inference.
   */
  build?: Array<
    | { ints: { n: number; lo: number; hi: number; seed: number } }
    | { sequence: { n: number; start: number; step: number } }
    | null
  >;
}

